import{_ as o,o as t,c as p,a5 as a}from"./chunks/framework.BPFk9-tb.js";const d=JSON.parse('{"title":"写作课作业-097","description":"","frontmatter":{"date":"2020-10-27T23:16:48","title":"写作课作业-097","categories":["写作","作业","一年顶十年"],"tags":["写作","作业","一年顶十年"]},"headers":[{"level":2,"title":"知识点与思考","slug":"知识点与思考","link":"#知识点与思考","children":[]}],"relativePath":"posts/homework/097.md","filePath":"posts/homework/097.md"}'),r={name:"posts/homework/097.md"};function l(s,e,c,i,_,n){return t(),p("div",null,[...e[0]||(e[0]=[a('<blockquote><p>10.27《一年定十年》之《状态 如何成为一个更在状态的狠人？》</p></blockquote><h2 id="知识点与思考" tabindex="-1">知识点与思考 <a class="header-anchor" href="#知识点与思考" aria-label="Permalink to &quot;知识点与思考&quot;">​</a></h2><blockquote><p>我经常对自己说一句话：“你是干大事的人“。</p></blockquote><p>和笑来老师的&quot;咱是谁啊？！&quot;对应起来了，都可以给自己做心理建设，提醒自己。</p><blockquote><p>远离总是打击你的人。</p></blockquote><p>我们要做励志的兔子，就要从鼓励身边的人开始。而总是打击你的人，会让你的进化之路更加漫长，何况在你进化的时候被打击很可能就进化不成功了，因为你要经过一段很长的看不到收益的过程。</p><blockquote><p>墙上挂字有什么用——这些字可以用来提醒自己，同时帮助自己调整心态和行为。</p></blockquote><p>要相信重复的力量。</p><blockquote><p>钱是人胆。缺钱，少的是底气。缺钱，多的是烦恼。</p></blockquote><p>碰到的几个90后的创造力不错是否和没有经济压力有关呢？</p><p>自己农村出来的，因为缺钱的各种吵吵闹闹倒也是看过不少。</p><hr><p>欢迎联系我</p><p>微信号 ：Crazy_Airhead</p><p>Mixin ID : 1091586</p><p>定投课堂邀请码：6DYMBFP061</p><p>李笑来写作课邀请码：38MDGFYZK8</p><p>水龙头邀请码：FDJQHJ</p>',18)])])}const k=o(r,[["render",l]]);export{d as __pageData,k as default};
